// n8n Code node  |  Mode: "Run Once for All Items"  |  Language: JavaScript
// Input: all rows from the Google Sheets "Get Row(s)" node
// Output: one item with stats, week-over-week change, and out-of-limit alerts

// ---------- EDIT THESE ----------
const DAYS = 7;                                         // reporting window
const METRICS = ['Temperature', 'Pressure', 'Yield'];   // must match your sheet headers exactly
const LIMITS = {                                        // set only the limits you care about
  Temperature: { max: 85 },                             // e.g. reactor temp above 85 °C
  Pressure:    { max: 5 },
  Yield:       { min: 90 },
};
// --------------------------------

const rows = $input.all().map(i => i.json);

const now = new Date();
const startCurrent = new Date(now); startCurrent.setDate(now.getDate() - DAYS);
const startPrevious = new Date(now); startPrevious.setDate(now.getDate() - 2 * DAYS);

const dateOf = r => new Date(r.Date);
const current = rows.filter(r => dateOf(r) >= startCurrent && dateOf(r) <= now);
const previous = rows.filter(r => dateOf(r) >= startPrevious && dateOf(r) < startCurrent);

const round = n => Math.round(n * 100) / 100;

function stats(data, metric) {
  const v = data.map(r => parseFloat(r[metric])).filter(x => !isNaN(x));
  if (!v.length) return null;
  const total = v.reduce((a, b) => a + b, 0);
  return { count: v.length, total: round(total), avg: round(total / v.length), min: Math.min(...v), max: Math.max(...v) };
}

const summary = {};
for (const m of METRICS) {
  const cur = stats(current, m);
  const prev = stats(previous, m);
  let changePct = null;
  if (cur && prev && prev.avg !== 0) changePct = round(((cur.avg - prev.avg) / prev.avg) * 100);
  summary[m] = { ...cur, previousAvg: prev ? prev.avg : null, avgChangePct: changePct };
}

// Flag readings outside limits
const alerts = [];
for (const r of current) {
  for (const m of METRICS) {
    const val = parseFloat(r[m]);
    const lim = LIMITS[m];
    if (isNaN(val) || !lim) continue;
    if (lim.max !== undefined && val > lim.max) alerts.push(`${m} ${val} on ${r.Date} is above the limit of ${lim.max}`);
    if (lim.min !== undefined && val < lim.min) alerts.push(`${m} ${val} on ${r.Date} is below the limit of ${lim.min}`);
  }
}

return [{
  json: {
    period: `${startCurrent.toISOString().slice(0, 10)} to ${now.toISOString().slice(0, 10)}`,
    rowsInPeriod: current.length,
    summary,
    alertCount: alerts.length,
    alerts,
  },
}];
